fn largest_price(keys: [str]) -> str:
    """The key with the largest value; the first such key on a tie."""
    prices = parallel([lambda: price(k) for k in keys])
    max_idx = 0
    for i, p in enumerate(prices):
        if p > prices[max_idx]:
            max_idx = i
    return keys[max_idx]

