fn above_price(keys: [str], limit: int) -> [str]:
    """The keys whose value is above `limit`, in order."""
    prices = parallel([lambda: price(k) for k in keys])
    result: [str] = []
    for i in range(len(keys)):
        if prices[i] > limit:
            result.append(keys[i])
    return result

